#!/usr/bin/env python3
# -*- coding: utf-8 -*-
"""КОНВЕЙЕР v3 — патчер RUVSON_QUANTUM_FULLY_LOADED.html (СИНГУЛЯР · КУБ-2026).

Что делает (2026-10-02):
  1. Лечит сломанный доктайп: каталог на 107 треков был вшит ВНУТРЬ <!DOCTYP…E html>
     — браузер глотал его как мусор, плеер жил по старому каталогу (85 треков).
  2. Ставит полный каталог 107 (уникальные номера 1..107, дубль №71 разрулен).
  3. Раскладывает аудио ПО КОНТЕНТУ (проверено ASR-распознаванием): в т.ч. полное
     «Крик в тишине» закреплено за оригиналом, ремикс играет своё превью, у
     «Цени моменты» снято чужое аудио.
  4. Кнопка «весь текст» (TXT): плашка «текст не добавлен» вместо голого заголовка,
     тост «сначала выберите трек» до выбора; кольца I..IX без undefined; метки
     прослушанного по номерам треков (kub26_heard_v2); превью помечены «· превью 30 с».

Запуск:  python accept_conveyor_v3.py [путь к RUVSON_QUANTUM_FULLY_LOADED.html]
Выход:   рядом RUVSON_QUANTUM_v3.html (оригинал не трогается).
"""
import gzip, base64, json, os, re, sys

PAYLOAD_GZ_B64 = ""

def load_payload():
    return json.loads(gzip.decompress(base64.b64decode(PAYLOAD_GZ_B64)).decode('utf-8'))

def find_source():
    if len(sys.argv) > 1:
        return sys.argv[1]
    here = os.path.dirname(os.path.abspath(__file__))
    cands = []
    for root, dirs, files in os.walk(here):
        dirs[:] = [d for d in dirs if d not in ('.git', 'node_modules', '__pycache__')]
        for f in files:
            if f.lower().endswith('.html') and 'quantum' in f.lower() and 'v3' not in f.lower():
                cands.append(os.path.join(root, f))
    if not cands:
        for d in (os.path.expanduser('~\\Downloads'), os.path.expanduser('~\\Desktop'),
                  os.path.expanduser('~/Downloads'), os.path.expanduser('~/Desktop')):
            if os.path.isdir(d):
                for f in os.listdir(d):
                    if f.lower().endswith('.html') and 'quantum' in f.lower():
                        cands.append(os.path.join(d, f))
    if len(cands) == 1:
        return cands[0]
    if not cands:
        sys.exit('Не нашёл RUVSON_QUANTUM_FULLY_LOADED.html — укажи путь аргументом.')
    print('Нашёл несколько файлов:')
    for i, c in enumerate(cands):
        print(f'  [{i}] {c}')
    return cands[int(input('Номер файла: ').strip())]

def balanced(txt, start, opener, closer):
    depth = in_str = esc = 0
    for k in range(start, len(txt)):
        c = txt[k]
        if in_str:
            if esc: esc = False
            elif c == '\\': esc = True
            elif c == '"': in_str = False
        else:
            if c == '"': in_str = True
            elif c == opener: depth += 1
            elif c == closer:
                depth -= 1
                if depth == 0: return k + 1
    raise ValueError('не найден баланс ' + opener + closer)

def main():
    p = load_payload()
    catalog = p['catalog']
    audio_map = p['audio_map']     # новый_номер → старый ключ TRACK_AUDIO
    preview = p['preview']
    vec_map = p['vec_map']

    src = find_source()
    print('источник:', src)
    txt = open(src, 'rb').read().decode('utf-8', errors='replace')
    if 'window.VEC_BY_TITLE' in txt:
        sys.exit('Файл уже пропатчен (v2/v3). Выход.')

    h = txt.find('<html data-motion')
    if h < 0:
        sys.exit('Не нашёл <html data-motion — файл не тот?')
    body_and_head = txt[h:]

    # каталог
    ib = body_and_head.find('window.TRACKS = [', 100000)
    jb = body_and_head.find('[', ib)
    eb = balanced(body_and_head, jb, '[', ']')
    body_and_head = body_and_head[:jb] + json.dumps(catalog, ensure_ascii=False) + body_and_head[eb:]

    # аудио: новый номер → URI старого слота
    i1 = body_and_head.find('var TRACK_AUDIO = ')
    j1 = body_and_head.find('{', i1)
    e1 = balanced(body_and_head, j1, '{', '}')
    raw = re.sub(r'([{,]\s*)(\d+)(\s*:)', r'\1"\2"\3', body_and_head[j1:e1])
    raw = re.sub(r',\s*}$', '}', raw.strip())
    old_audio = json.loads(raw)
    new_audio = {}
    for new_num, old_key in audio_map.items():
        if old_key in old_audio:
            new_audio[new_num] = old_audio[old_key]
        else:
            print('ВНИМАНИЕ: нет старого ключа', old_key)
    audio_js = 'var TRACK_AUDIO = {\n' + ',\n'.join(
        f'  {k}: "{v}"' for k, v in sorted(new_audio.items(), key=lambda x: int(x[0]))) + '\n};'
    preview_js = 'var TRACK_PREVIEW = {' + ','.join(f'{k}:1' for k in sorted(preview, key=int)) + '};'
    body_and_head = body_and_head[:i1] + preview_js + '\n' + audio_js + body_and_head[e1:]

    vec_js = 'window.VEC_BY_TITLE = ' + json.dumps(vec_map, ensure_ascii=False) + ';\n'
    body_and_head = body_and_head.replace('window.VECTORS = ', vec_js + 'window.VECTORS = ', 1)

    reps = [
        ('const RING_NAMES = ["I", "II", "III", "IV", "V"];',
         'const RING_NAMES = ["I", "II", "III", "IV", "V", "VI", "VII", "VIII", "IX"];'),
        ('RING_NAMES[Math.floor(i / 12)]',
         'RING_NAMES[Math.min(Math.floor(i / 12), RING_NAMES.length - 1)]'),
        ('localStorage.getItem("kub26_heard")', 'localStorage.getItem("kub26_heard_v2")'),
        ('localStorage.setItem("kub26_heard",', 'localStorage.setItem("kub26_heard_v2",'),
        ('heard.has(i) ? " is-heard" : ""', 'heard.has(Number(t.i)) ? " is-heard" : ""'),
        ('if (!heard.has(i)) {\n    heard.add(i);',
         'if (!heard.has(Number(t.i))) {\n    heard.add(Number(t.i));'),
        ('if (pState) pState.textContent = t.s;',
         'if (pState) { var _ai = parseInt(t.i, 10); var _lb = (STATE_LABEL[t.s] || t.s);'
         ' if (window.TRACK_AUDIO && TRACK_AUDIO[_ai] && typeof TRACK_PREVIEW !== "undefined" && TRACK_PREVIEW[_ai]) _lb += " · превью 30 с";'
         ' else if (window.TRACK_AUDIO && TRACK_AUDIO[_ai]) _lb += " · полный";'
         ' pState.textContent = _lb; }', 1),
        ('if (pVec) pVec.textContent = VECTORS ? (VECTORS[i] || "") : "";',
         'if (pVec) pVec.textContent = (window.VEC_BY_TITLE && VEC_BY_TITLE[t.t]) || "";', 1),
        ('function parseLyrics(t) {\n'
         '  const raw = (t.l || t.t).split(/\\n+/).map((s) => s.trim()).filter(Boolean);\n'
         '  if (!raw.length) return [{ chip: false, aside: false, text: t.t }];',
         'function parseLyrics(t) {\n'
         '  const _src = (t.l && String(t.l).trim()) ? t.l : "";\n'
         '  if (!_src) return [{ chip: true, aside: false, text: "текст не добавлен" }, { chip: false, aside: false, text: t.t }];\n'
         '  const raw = _src.split(/\\n+/).map((s) => s.trim()).filter(Boolean);\n'
         '  if (!raw.length) return [{ chip: true, aside: false, text: "текст не добавлен" }, { chip: false, aside: false, text: t.t }];', 1),
        ('btnMode.addEventListener("click", () => {\n  fullMode = !fullMode;',
         'btnMode.addEventListener("click", () => {\n'
         '  if (activeIdx < 0) { if (typeof showToast === "function") showToast("сначала выберите трек"); return; }\n'
         '  fullMode = !fullMode;', 1),
    ]
    for rep in reps:
        old, new = rep[0], rep[1]
        once = len(rep) > 2
        if old not in body_and_head:
            print('ВНИМАНИЕ: якорь не найден:', old[:60].replace('\n', '\\n'))
            continue
        body_and_head = body_and_head.replace(old, new) if not once else body_and_head.replace(old, new, 1)

    final = '<!DOCTYPE html>\n' + body_and_head
    assert final.count('window.TRACKS = ') == 1

    out = os.path.join(os.path.dirname(src) or '.', 'RUVSON_QUANTUM_v3.html')
    with open(out, 'w', encoding='utf-8') as f:
        f.write(final)
    print(f'ГОТОВО: {out} ({len(final)/1e6:.1f} МБ)')
    print(f'каталог: {len(catalog)} треков | аудио: {len(new_audio)} песен | превью: {len(preview)}')
    print('Нумерация 1..107, названия совпадают с песнями (сверено по контенту).')

if __name__ == '__main__':
    main()
